), matched as (
  select s.*, v.id as vehicle_id, a.id as author_id,
    (s.needs_review or (s.author_label is not null and a.id is null)) as review_flag
  from import_source s
  left join public.makes mk on lower(btrim(mk.name)) = lower(btrim(s.source_make))
  left join public.models mo on mo.make_id = mk.id and lower(btrim(mo.name)) = lower(btrim(s.model))
  left join public.model_year_vehicles v on v.model_id = mo.id and v.model_year = s.model_year
  left join public.authors a on lower(btrim(a.label)) = lower(btrim(s.author_label))
), deadline_updates as (
  update public.model_years y set changeover_deadline = d.deadline
  from (values (2024, date '2023-12-21'), (2025, date '2024-12-20'), (2026, date '2025-12-19'), (2027, date '2026-12-18')) as d(year, deadline)
  where y.year = d.year and y.changeover_deadline is null returning y.year
), url_updates as (
  update public.model_year_vehicles v set public_url = m.public_url
  from matched m where v.id = m.vehicle_id and m.public_url is not null and (v.public_url is null or btrim(v.public_url) = '')
  returning v.id
), entry_import as (
  insert into public.changeover_entries (model_year_vehicle_id, status, assigned_author_id, notes, source_provenance, needs_review)
  select m.vehicle_id, m.status::public.changeover_status, m.author_id, coalesce(m.notes, ''),
    jsonb_build_array(jsonb_build_object('source_sheet', m.source_sheet, 'source_row', m.source_row, 'raw_status', nullif(m.raw_status, ''), 'raw_author', nullif(m.raw_author, ''), 'review_flag', m.review_flag)), m.review_flag
  from matched m where m.vehicle_id is not null
  on conflict (model_year_vehicle_id) do nothing returning id
)
select
  (select count(*) from import_source) as source_rows,
  (select count(*) from matched where vehicle_id is not null) as catalog_matches,
  (select count(*) from matched where vehicle_id is null) as unmatched_catalog_rows,
  (select array_agg(format('%s %s (%s)', source_make, model, model_year) order by source_make, model, model_year)
     from (select distinct source_make, model, model_year from matched where vehicle_id is null order by source_make, model, model_year limit 25) missing) as unmatched_catalog_examples,
  (select count(*) from matched where nullif(btrim(raw_author), '') is not null and upper(btrim(raw_author)) <> 'OPEN' and author_id is null) as unresolved_source_authors,
  (select array_agg(distinct raw_author order by raw_author) from matched where nullif(btrim(raw_author), '') is not null and upper(btrim(raw_author)) <> 'OPEN' and author_id is null) as unresolved_author_names,
  (select count(*) from matched where review_flag) as rows_needing_review,
  (select count(*) from entry_import) as inserted_entries,
  (select count(*) from matched where vehicle_id is not null) - (select count(*) from entry_import) as existing_entries_preserved,
  (select count(*) from url_updates) as public_urls_filled,
  (select count(*) from deadline_updates) as deadlines_set;
